import { Component, Prop, h, Host } from '@stencil/core';
import classnames from 'classnames';
import { formatCSSLength } from '@src/shared/dom';

const prefix = 'space';

// type D = never extends unknown ? boolean : never;

/**
 * @slot default - Content items rendered inside the space container.
 */
@Component({
  tag: 'ks-space',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsSpace {
  /** The direction items are placed. Can be 'horizontal' or 'vertical'. */
  @Prop() direction: 'vertical' | 'horizontal' = 'horizontal';

  /** Whether to use compact layout, which removes the gap between items. If true, the `gap` prop is ignored. */
  @Prop() compact?: boolean;

  /** The gap between items. This prop is only effective when `compact` is not true. Can be a number (in pixels) or a string (e.g., "8px", "1rem"). */
  @Prop() gap?: string | number;

  render() {
    const classes = classnames([`${prefix}`, `${prefix}--${this.direction}`], {
      [`${prefix}--compact`]: this.compact,
    });
    const styles = {
      gap: this.compact ? 'none' : formatCSSLength(this.gap),
    };
    return (
      <Host class="KsSpace">
        <div class={classes} style={styles}>
          <slot></slot>
        </div>
      </Host>
    );
  }
}
